/**
 * The browser's mojom surface, as this bundle sees it.
 *
 * The bindings are generated by Chromium's mojom pipeline and served next to the
 * bundle (`chrome://hook/hook.mojom-webui.js`), so they cannot be imported at
 * build time: the specifier is left alone and resolved at run time. In
 * `pnpm browser:ui:dev` there is no browser behind the page, so `hookHandler()`
 * answers null and the dock falls back to its local transport.
 */

export interface Tab {
  index: number;
  id: number;
  active: boolean;
  title: string;
  /** The committed URL, without its fragment or credentials. */
  url: string;
  domain: string;
}

export interface ChatSummary {
  id: string;
  title: string;
  /** Milliseconds since the epoch. */
  updatedAt: number;
  busy: boolean;
  unsynced: boolean;
}

export interface ChatToolCall {
  id: string;
  name: string;
  /** Raw JSON arguments exactly as the model produced them. */
  arguments: string;
}

export interface ChatCompaction {
  messages: number;
  tokensBefore: number;
  tokensAfter: number;
}

export interface ChatMessage {
  id: string;
  role: string;
  content: string;
  status: string;
  hidden: boolean;
  error: string;
  /** What the model thought before it answered; advanced mode draws it. */
  reasoning: string;
  /** Calls this message made; each result is a `tool` row keyed by `toolCallId`. */
  toolCalls: ChatToolCall[];
  /** Set on a `tool` result: the call it answers. */
  toolCallId: string;
  /** Set on a compaction: what the summary folded away. */
  compaction?: ChatCompaction;
}

export interface ChatView {
  chat: ChatSummary;
  messages: ChatMessage[];
}

export interface SignInView {
  signedIn: boolean;
  /** Whether a Hook app answers on this computer. */
  available: boolean;
  /** signed_out | pending | signed_in */
  state: string;
  userCode: string;
  verificationUrl: string;
  email: string;
  name: string;
  message: string;
}

export interface HookPageHandler {
  getTabs(): Promise<{ tabs: Tab[] }>;
  showUI(): void;
  /** Asks the host to hide the side panel; a no-op in a tab. */
  closeUI(): void;
  getChannel(): Promise<{ available: boolean; reason: string }>;
  /** Advanced mode, from the running host. False when the host is too old. */
  getSettings(): Promise<{ advancedMode: boolean }>;
  listChats(): Promise<{ chats: ChatSummary[]; error: string }>;
  getChat(id: string): Promise<{ chat: ChatView | null; error: string }>;
  createChat(): Promise<{ id: string; error: string }>;
  /** The browser builds the page frame itself; the page sends words only. */
  sendMessage(
    id: string,
    text: string,
  ): Promise<{ ok: boolean; error: string }>;
  stopMessage(id: string): void;
  getSignIn(): Promise<SignInView>;
  startSignIn(): Promise<{ view: SignInView; error: string }>;
  cancelSignIn(): Promise<void>;
}

let handler: HookPageHandler | null = null;
let unavailable = false;

/** The page's handler, or null when this page is not served by the browser. */
export async function hookHandler(): Promise<HookPageHandler | null> {
  if (handler) return handler;
  if (unavailable) return null;
  try {
    // Resolved against this module's own URL — `chrome://hook-panel/panel.mjs`
    // next to `hook.mojom-webui.js` — rather than written as a literal, because a
    // literal makes Vite's dev server try to resolve a file that only exists in
    // the browser's pak (and fail the page).
    const specifier = new URL("./hook.mojom-webui.js", import.meta.url).href;
    const module = (await import(/* @vite-ignore */ specifier)) as {
      PageHandler: { getRemote(): HookPageHandler };
    };
    handler = module.PageHandler.getRemote();
    return handler;
  } catch {
    unavailable = true;
    return null;
  }
}

/** The tab that is selected, which is the one a message is about. */
export function activeTab(tabs: Tab[]): Tab | undefined {
  return tabs.find((tab) => tab.active) ?? tabs[0];
}
